private static StringBuilder errorAt(final JexlNode node) {
        final JexlInfo info = node != null? detailedInfo(node, node.jexlInfo()) : null;
        final StringBuilder msg = new StringBuilder();
        if (info != null) {
            msg.append(info.toString());
        } else {
            msg.append("?:");
        }
        msg.append(' ');
        return msg;
    }

@Deprecated
