private void setFeature(final int feature, final boolean flag) {
        if (flag) {
            flags |= (1 << feature);
        } else {
            flags &= ~(1L << feature);
        }
    }

private boolean getFeature(final int feature) {
        return (flags & (1L << feature)) != 0L;
    }

